#include "stdlib/math/base/special/polygamma.h"
#include <stdio.h>

int main( void ) {
	const int32_t n[] = { 0, 1, 2, 3, 5 };
	const double x[] = { 1.0, 1.5, 2.0, 2.5, 3.0 };

	double y;
	int i, j;
	for ( i = 0; i < 5; i++ ) {
		for ( j = 0; j < 5; j++ ) {
			y = stdlib_base_polygamma( n[i], x[j] );
			printf( "polygamma(%d, %lf) = %lf\n", n[i], x[j], y );
		}
	}
}